alter function public.record_purchase(bigint,bigint,jsonb,date,text,numeric,numeric,text,text,text,text,text) rename to record_purchase_core; alter function public.record_vendor_payment(bigint,numeric,text,jsonb,date,text,text,text,text,text) rename to record_vendor_payment_core; create or replace function public.record_purchase(p_vendor_id bigint,p_warehouse_id bigint,p_items jsonb,p_purchase_date date default current_date,p_invoice_number text default null,p_discount numeric default 0,p_tax numeric default 0,p_notes text default null,p_idempotency_principal text default null,p_idempotency_operation text default 'purchase.create',p_idempotency_key text default null,p_request_fingerprint text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare r jsonb; pid bigint; total numeric; subtotal numeric; tax numeric; pdate date; jid bigint; begin r:=public.record_purchase_core(p_vendor_id,p_warehouse_id,p_items,p_purchase_date,p_invoice_number,p_discount,p_tax,p_notes,p_idempotency_principal,p_idempotency_operation,p_idempotency_key,p_request_fingerprint); pid:=(r->'response_body'->'data'->'purchase'->>'id')::bigint; select p.total,p.subtotal,p.tax,p.purchase_date into total,subtotal,tax,pdate from public.purchases p where p.id=pid; insert into public.vendor_payable_ledger_entries(vendor_id,entry_type,reference_type,reference_id,debit,credit,entry_date,description) values(p_vendor_id,'PURCHASE','PURCHASE',pid,0,total,pdate,'Purchase payable') on conflict(entry_type,reference_type,reference_id) do nothing; insert into public.accounting_journal_entries(entry_date,source_type,source_id,description) values(pdate,'PURCHASE',pid,'Purchase payable') on conflict(source_type,source_id) do nothing returning id into jid; if jid is not null then insert into public.accounting_journal_lines(journal_entry_id,account_code,debit,credit,description) values(jid,'1200',greatest(subtotal-coalesce(p_discount,0),0),0,'Inventory from purchase'),(jid,'1300',coalesce(tax,0),0,'Input tax from purchase'),(jid,'2000',0,total,'Vendor accounts payable'); end if; return r; end; $$; create or replace function public.record_vendor_payment(p_vendor_id bigint,p_amount numeric,p_payment_method text,p_allocations jsonb,p_payment_date date default current_date,p_reference text default null,p_notes text default null,p_principal_scope text default 'service_role',p_idempotency_key text default null,p_request_fingerprint text default null) returns bigint language plpgsql security definer set search_path=public as $$ declare pid bigint;jid bigint;acct text;begin pid:=public.record_vendor_payment_core(p_vendor_id,p_amount,p_payment_method,p_allocations,p_payment_date,p_reference,p_notes,p_principal_scope,p_idempotency_key,p_request_fingerprint); insert into public.vendor_payable_ledger_entries(vendor_id,entry_type,reference_type,reference_id,debit,credit,entry_date,description) values(p_vendor_id,'PAYMENT','VENDOR_PAYMENT',pid,p_amount,0,coalesce(p_payment_date,current_date),'Vendor payment against payable') on conflict(entry_type,reference_type,reference_id) do nothing; acct:=case p_payment_method when 'CASH' then '1000' when 'BANK' then '1010' else '1090' end; insert into public.accounting_journal_entries(entry_date,source_type,source_id,description) values(coalesce(p_payment_date,current_date),'VENDOR_PAYMENT',pid,'Vendor payment') on conflict(source_type,source_id) do nothing returning id into jid; if jid is not null then insert into public.accounting_journal_lines(journal_entry_id,account_code,debit,credit,description) values(jid,'2000',p_amount,0,'Reduce vendor accounts payable'),(jid,acct,0,p_amount,'Vendor payment funding account'); end if; return pid; end; $$; revoke all on function public.record_purchase_core(bigint,bigint,jsonb,date,text,numeric,numeric,text,text,text,text,text) from public,anon,authenticated; revoke all on function public.record_vendor_payment_core(bigint,numeric,text,jsonb,date,text,text,text,text,text) from public,anon,authenticated; revoke all on function public.record_purchase(bigint,bigint,jsonb,date,text,numeric,numeric,text,text,text,text,text) from public,anon,authenticated; grant execute on function public.record_purchase(bigint,bigint,jsonb,date,text,numeric,numeric,text,text,text,text,text) to service_role; revoke all on function public.record_vendor_payment(bigint,numeric,text,jsonb,date,text,text,text,text,text) from public,anon,authenticated; grant execute on function public.record_vendor_payment(bigint,numeric,text,jsonb,date,text,text,text,text,text) to service_role;